using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchHistoryFileStore{private readonly string _path;public AndroidResearchHistoryFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(IReadOnlyList<AndroidResearchHistoryEntry> value){ArgumentNullException.ThrowIfNull(value);Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public IReadOnlyList<AndroidResearchHistoryEntry> Load()=>JsonSerializer.Deserialize<AndroidResearchHistoryEntry[]>(File.ReadAllText(_path))??throw new InvalidOperationException("Research history JSON is invalid.");}
